<?php require_once __DIR__ . '/includes/auth.php'; $user=require_role(['owner','branch_manager','cashier','waiter','kitchen','inventory_manager','accountant']); $pdo=db(); check_tenant_active($pdo); $tid=require_tenant(); $base=''; $active='customers'; $pageTitle='Customers & Loyalty'; $bid=branch_id();
function q1(PDO $pdo,string $sql,array $a){ $s=$pdo->prepare($sql); $s->execute($a); return $s->fetchColumn(); }
function qa(PDO $pdo,string $sql,array $a): array { $s=$pdo->prepare($sql); $s->execute($a); return $s->fetchAll(); }

if (is_post()) { verify_csrf(); $act=$_POST['action']??'';
  if($act==='save'){ if(!empty($_POST['id'])) $pdo->prepare('UPDATE customers SET name=?,email=?,phone=?,address=?,membership=? WHERE id=? AND tenant_id=?')->execute([trim($_POST['name']),trim($_POST['email']??''),trim($_POST['phone']??''),trim($_POST['address']??''),$_POST['membership']??'regular',(int)$_POST['id'],$tid]);
    else $pdo->prepare('INSERT INTO customers(tenant_id,name,email,phone,address,membership,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([$tid,trim($_POST['name']),trim($_POST['email']??''),trim($_POST['phone']??''),trim($_POST['address']??''),$_POST['membership']??'regular']); flash('success','Customer saved.'); }
  elseif($act==='delete'){ $pdo->prepare('DELETE FROM customers WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tid]); flash('success','Customer deleted.'); }
  elseif($act==='points'){ $pdo->prepare('UPDATE customers SET loyalty_points=GREATEST(0,loyalty_points+?) WHERE id=? AND tenant_id=?')->execute([(int)$_POST['points'],(int)$_POST['id'],$tid]); flash('success','Loyalty points adjusted.'); }
  redirect('customers.php'); }
$search=trim($_GET['q']??''); $sql='SELECT * FROM customers WHERE tenant_id=?'; $a=[$tid]; if($search){ $sql.=' AND (name LIKE ? OR phone LIKE ? OR email LIKE ?)'; $a[]='%'.$search.'%'; $a[]='%'.$search.'%'; $a[]='%'.$search.'%'; }
$rows=qa($pdo,$sql.' ORDER BY total_spent DESC',$a);
$edit=null; $history=[]; if(!empty($_GET['edit'])){ $s=$pdo->prepare('SELECT * FROM customers WHERE id=? AND tenant_id=?'); $s->execute([(int)$_GET['edit'],$tid]); $edit=$s->fetch(); }
if(!empty($_GET['history'])){ $history=qa($pdo,'SELECT * FROM orders WHERE customer_id=? AND tenant_id=? ORDER BY id DESC LIMIT 20',[(int)$_GET['history'],$tid]); }
include __DIR__ . '/includes/header.php'; ?>
<div class="card p-3 mb-3"><form class="row g-2" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>">
<div class="col-md-3"><input class="form-control" name="name" placeholder="Name" value="<?= e($edit['name']??'') ?>" required></div><div class="col-md-2"><input class="form-control" name="phone" placeholder="Phone" value="<?= e($edit['phone']??'') ?>"></div>
<div class="col-md-3"><input class="form-control" name="email" placeholder="Email" value="<?= e($edit['email']??'') ?>"></div><div class="col-md-2"><input class="form-control" name="address" placeholder="Address" value="<?= e($edit['address']??'') ?>"></div>
<div class="col-md-1"><select class="form-select" name="membership"><?php foreach(['regular','silver','gold','vip'] as $m): ?><option <?= ($edit['membership']??'regular')===$m?'selected':'' ?>><?= $m ?></option><?php endforeach; ?></select></div>
<div class="col-md-1"><button class="btn btn-primary w-100"><?= $edit?'Update':'Add' ?></button></div></form></div>
<form class="mb-3" method="get"><div class="input-group"><input class="form-control" name="q" placeholder="Search customers…" value="<?= e($search) ?>"><button class="btn btn-outline-primary">Search</button></div></form>
<div class="card p-0 overflow-auto"><table class="table mb-0"><tr><th>Customer</th><th>Contact</th><th>Membership</th><th>Loyalty points</th><th>Total spent</th><th>Visits</th><th></th></tr>
<?php foreach($rows as $r): ?><tr><td><strong><?= e($r['name']) ?></strong></td><td class="small"><?= e($r['phone']??'') ?><br><?= e($r['email']??'') ?></td><td><span class="badge bg-info"><?= e($r['membership']) ?></span></td><td><?= $r['loyalty_points'] ?>
<form method="post" class="d-inline-flex gap-1"><?= csrf_field() ?><input type="hidden" name="action" value="points"><input type="hidden" name="id" value="<?= $r['id'] ?>"><input class="form-control form-control-sm" style="width:70px" type="number" name="points" placeholder="+/-"><button class="btn btn-sm btn-outline-primary">Set</button></form></td>
<td><?= money($r['total_spent']) ?></td><td><?= $r['visits'] ?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-secondary" href="?history=<?= $r['id'] ?>">History</a> <a class="btn btn-sm btn-outline-primary" href="?edit=<?= $r['id'] ?>">Edit</a> <form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Delete customer?">Delete</button></form></td></tr><?php endforeach; ?></table></div>
<?php if($history): ?><div class="card p-3 mt-3"><h6>Order history</h6><table class="table mb-0"><tr><th>Order</th><th>Status</th><th>Total</th><th>Date</th><th></th></tr><?php foreach($history as $o): ?><tr><td><?= e($o['order_number']) ?></td><td><?= e($o['status']) ?></td><td><?= money($o['total']) ?></td><td><?= e($o['created_at']) ?></td><td><a class="btn btn-sm btn-outline-secondary" href="receipt.php?id=<?= $o['id'] ?>" target="_blank">Receipt</a></td></tr><?php endforeach; ?></table></div><?php endif; ?>
